// For the #WCCChallenge, theme: "psychedelic".

var palette = ['#B41CB9AA', '#FE6410AA', '#F4CD28AA', '#5EAF33AA', '#A01F1EAA', '#011369AA'];

function setup() {
	createCanvas(windowWidth, windowHeight);
}

function draw() {
	let divider = 25 + sin(frameCount / 300) * 20;
	background(0, 40);
	noStroke();
	translate(width / 2, height / 2);
	for (let j = 0; j < 24; j++) {
		let r = map(j, 0, 24, 0, width)
		rotate((0.5 - noise(j / divider, frameCount / 600)) * (TAU / j) * sin(frameCount / 200));
		for (let i = 0; i < 120; i++) {
			let a = i * TAU / 120;
			if (i % 10 == 0) continue;
			fill(palette[(j+i) % palette.length]);
			push();
			scale(0.5 + sin(j / 4 + frameCount / 60) / 24);
			beginShape();
			vertex(r * cos(a), r * sin(a));
			vertex((r + width / 30) * cos(a), (r + width / 30) * sin(a));
			vertex((r + width / 30) * cos(a + TAU / 120), (r + width / 30) * sin(a + TAU / 120));
			vertex(r * cos(a + TAU / 120), r * sin(a + TAU / 120));
			endShape();
			pop();
		}
	}
}
